class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: on Unix, empty env vars now return null
        // instead of "". Use a sentinel or check existence explicitly.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!HasEnvironmentVariable("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool HasEnvironmentVariable(string name)
    {
        // Reliably distinguishes "not set" from "set to empty" on .NET 9+
        return Environment.GetEnvironmentVariables().Contains(name);
    }
}

